insert into public.content_item_categories(item_id,game_id,category_id,sort_order,enabled) select item_id,'icebreaker',category_id,sort_order,true from decked_icebreaker_v1_active on conflict(item_id,game_id,category_id) do update set sort_order=excluded.sort_order,enabled=true;
insert into public.content_item_versions(item_id,version,body,normalized_body,metadata,editorial_status,change_note) select item_id,next_version,body,lower(regexp_replace(body,'[^[:alnum:]'']+',' ','g')),metadata,'published','Icebreaker playable V1 editorial revision' from decked_icebreaker_v1_revisions on conflict(item_id,version) do update set body=excluded.body,normalized_body=excluded.normalized_body,metadata=excluded.metadata,editorial_status='published',change_note=excluded.change_note;
insert into public.content_releases(id,game_id,status,item_count,membership_count,checksum,notes,published_at) values('21647967-b2f1-51f5-8db8-2d6016c48051'::uuid,'icebreaker','published',176,176,'cf33cdad8641b0e6ce99dd661be7f3936a31ace0c5808605db412119e175d0ec','Icebreaker playable V1; 249 production identities archived and 1,500 legacy runtime prompts retained for saved-session resolution.',now()) on conflict(id) do update set status='published',item_count=176,membership_count=176,checksum=excluded.checksum,notes=excluded.notes,published_at=now();
insert into public.content_release_items(release_id,item_id,version,category_ids) select '21647967-b2f1-51f5-8db8-2d6016c48051'::uuid,item.id,item.published_version,array[selected.category_id] from decked_icebreaker_v1_active selected join public.content_items item on item.id=selected.item_id where item.game_id='icebreaker' and item.published_version is not null;
