-- Recovered from the linked project's Supabase migration history.

-- Icebreaker playable V1: 176 active cards, 249 preserved archived identities.
begin;

create temporary table decked_icebreaker_v1_active(item_id uuid primary key,category_id text not null,sort_order integer not null,body text not null,metadata jsonb not null,revised boolean not null) on commit drop;


do $$ declare matched integer; begin select count(*) into matched from public.content_items item join decked_icebreaker_v1_active selected on selected.item_id=item.id where item.game_id='icebreaker'; if matched<>176 then raise exception 'Icebreaker V1 inventory mismatch: expected 176 IDs, found %',matched; end if; end $$;

update public.content_items set lifecycle_status='archived',updated_at=now() where game_id='icebreaker';

update public.content_items item set lifecycle_status='active',updated_at=now() from decked_icebreaker_v1_active selected where item.id=selected.item_id and item.game_id='icebreaker';

update public.content_item_categories set enabled=false where game_id='icebreaker';


create temporary table decked_icebreaker_v1_revisions on commit drop as select selected.*,item.current_version+1 next_version from decked_icebreaker_v1_active selected join public.content_items item on item.id=selected.item_id where selected.revised;

update public.content_item_versions version set editorial_status='superseded' from decked_icebreaker_v1_revisions revised where version.item_id=revised.item_id and version.version=(select published_version from public.content_items where id=revised.item_id);


update public.content_items item set current_version=revised.next_version,published_version=revised.next_version,updated_at=now() from decked_icebreaker_v1_revisions revised where item.id=revised.item_id;

update public.content_item_versions version set metadata=coalesce(version.metadata,'{}'::jsonb)||selected.metadata from decked_icebreaker_v1_active selected join public.content_items item on item.id=selected.item_id where not selected.revised and version.item_id=item.id and version.version=item.published_version;

update public.content_releases set status='superseded' where game_id='icebreaker' and status='published';


delete from public.content_release_items where release_id='21647967-b2f1-51f5-8db8-2d6016c48051'::uuid;


commit;
